export const agentMarkdownByPath: Readonly<Record<string, string>> = {
  "/": "# temporal-calendar\n\n> Temporal-first building blocks for month, week, and day calendar interfaces.\n\nCanonical: https://calendar.gobrand.app/\n\nCoding agents should read https://calendar.gobrand.app/llms.txt before making Calendar changes.\n\nInstall the Calendar Agent Skill with `npx skills add go-brand/calendar`.\n\nReact installation: `pnpm add @gobrand/react-calendar @js-temporal/polyfill`.\n\nHuman documentation: https://calendar.gobrand.app/docs.\n",
  "/docs": "# React Calendar\n\n> Build month, week, and day calendars with React and Temporal.\n\nCanonical: https://calendar.gobrand.app/docs\n\nReact Calendar manages the current date, active view, navigation, and calendar geometry. You render it with your own components and styles.\n\nStart with one view and your events:\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCreateCalendar } from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\nfunction Calendar({ events }: { events: Event[] }) {\n  const calendar = useCreateCalendar({\n    views: { month: true },\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return calendar.activeView.weeks.map(week => (\n    <div key={week[0].id}>\n      {week.map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.length} events\n        </div>\n      ))}\n    </div>\n  ))\n}\n```\n\nBecause only `month` is enabled, `activeView` is a month view. Add `week` or `day` when you need them.\n\n[Build your first calendar](/docs/first-calendar) or [open the complete month/week/day example](/docs/examples/multi-view).\n",
  "/docs/installation": "# Installation\n\n> Get started with GoBrand React Calendar\n\nCanonical: https://calendar.gobrand.app/docs/installation\n\n## Install\n\n```bash\npnpm add @gobrand/react-calendar @js-temporal/polyfill\n# or\nnpm install @gobrand/react-calendar @js-temporal/polyfill\n```\n\nThe React package includes the core library - no separate installation needed.\n\n## TypeScript\n\nThe package is written in TypeScript and includes type definitions. No additional `@types` packages needed.\n\n## Temporal\n\nImport Temporal from the polyfill you installed above:\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst today = Temporal.Now.plainDateISO();\nconst meeting = Temporal.ZonedDateTime.from('2025-01-20T14:00:00-05:00[America/New_York]');\n```\n",
  "/docs/first-calendar": "# Your first calendar\n\n> Build a navigable month with one hook.\n\nCanonical: https://calendar.gobrand.app/docs/first-calendar\n\nEnable a view with `true`, pass your events, and tell the calendar where each event belongs.\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCreateCalendar } from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\nfunction Calendar({ events }: { events: Event[] }) {\n  const calendar = useCreateCalendar({\n    views: { month: true },\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return (\n    <section>\n      <h2>{calendar.title()}</h2>\n      {calendar.activeView.weeks.flat().map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n        </div>\n      ))}\n    </section>\n  )\n}\n```\n\nThat is the whole setup. TypeScript infers the event type, and `calendar.activeView` is a `MonthView` because month is the only enabled view.\n\n<CalendarPreview name=\"basic-month\" />\n\nThe preview is live. Its source uses small website-only components for markup and styles; its calendar state and month data come directly from `useCreateCalendar`.\n\n## What the library does\n\n- Keeps the current date and active view.\n- Moves with `previous()`, `next()`, and `today()`.\n- Gives you a localized `title()` and timezone-aware `visibleRange`.\n- Builds the month, week, or day data you render.\n\nYour app owns the markup, styles, data fetching, and caching.\n\n## Add week and day views\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: {\n    month: true,\n    week: true,\n    day: true,\n  },\n  items: events,\n  getDate: event => event.date,\n})\n```\n\nAn omitted view is unavailable. Use an options object instead of `true` when a timed week or day needs custom hours or slot length.\n\n[See the complete month/week/day example](/docs/examples/multi-view).\n",
  "/docs/data-and-suspense": "# Data and Suspense\n\n> Keep calendar controls available while a view loads its events.\n\nCanonical: https://calendar.gobrand.app/docs/data-and-suspense\n\nCreate the calendar without events above the Suspense boundary. Fetch and project the events inside the view.\n\n```tsx\nimport { Suspense } from 'react'\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useSuspenseQuery } from '@tanstack/react-query'\nimport {\n  CalendarProvider,\n  useCalendar,\n  useCalendarView,\n  useCreateCalendar,\n} from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\ntype CalendarProps = {\n  loadEvents(\n    start: Temporal.ZonedDateTime,\n    end: Temporal.ZonedDateTime,\n  ): Promise<Event[]>\n}\n\nfunction Calendar({ loadEvents }: CalendarProps) {\n  const calendar = useCreateCalendar({ views: { month: true } })\n\n  return (\n    <CalendarProvider calendar={calendar}>\n      <Controls />\n      <Suspense fallback={<p>Loading events…</p>}>\n        <MonthView loadEvents={loadEvents} />\n      </Suspense>\n    </CalendarProvider>\n  )\n}\n\nfunction Controls() {\n  const calendar = useCalendar()\n\n  return (\n    <nav>\n      <button onClick={calendar.previous}>Previous</button>\n      <strong>{calendar.title()}</strong>\n      <button onClick={calendar.next}>Next</button>\n    </nav>\n  )\n}\n\nfunction MonthView({ loadEvents }: CalendarProps) {\n  const calendar = useCalendar()\n  const { start, end } = calendar.visibleRange\n  const { data: events } = useSuspenseQuery({\n    queryKey: ['events', start.toString(), end.toString()],\n    queryFn: () => loadEvents(start, end),\n  })\n\n  const month = useCalendarView({\n    view: 'month',\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return month.weeks.map(week => (\n    <div key={week[0].id}>\n      {week.map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n        </div>\n      ))}\n    </div>\n  ))\n}\n```\n\n`Controls` does not unmount when `MonthView` suspends, so navigation remains available while events load.\nThe example assumes your app already has TanStack Query's `QueryClientProvider`.\n\n## Different data for each view\n\nEach `useCalendarView` call infers its own item type. A month view can use summaries while a timed week view uses full event records. The shared controller does not need to know either type.\n\n<CalendarPreview name=\"suspense-month\" />\n",
  "/docs/timezones-and-ranges": "# Timezones and visible ranges\n\n> Query half-open calendar ranges that remain correct across DST transitions.\n\nCanonical: https://calendar.gobrand.app/docs/timezones-and-ranges\n\nSet the calendar timezone once:\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  timeZone: 'America/New_York',\n})\n```\n\nThat timezone drives the initial date, `today()`, `isToday`, navigation ranges, and local-midnight boundaries. Calendar behavior does not fall back to the host timezone after a timezone is supplied.\n\n## Half-open query contract\n\n```ts\ntype VisibleRange = {\n  start: Temporal.ZonedDateTime\n  end: Temporal.ZonedDateTime\n}\n```\n\nUse `>= start` and `< end`. Adjacent ranges meet without gaps or duplicate boundary records, and the code never has to invent the final nanosecond of a day.\n\n```ts\nconst { start, end } = calendar.visibleRange\n\nawait db.event.findMany({\n  where: {\n    startsAt: { gte: start.toInstant(), lt: end.toInstant() },\n  },\n})\n```\n\n## DST is calendar geometry\n\nA local calendar day may contain 23, 24, or 25 elapsed hours. Calendar constructs each boundary from its own local midnight rather than adding 24 hours to an instant.\n",
  "/docs/controlled-state": "# Controlled state and routing\n\n> Synchronize calendar date and view with URLs or external application state.\n\nCanonical: https://calendar.gobrand.app/docs/controlled-state\n\nCalendar follows standard React controlled and uncontrolled conventions.\n\n| State | Controlled | Uncontrolled initial value |\n| --- | --- | --- |\n| Date | `date` / `onDateChange` | `defaultDate` |\n| View | `view` / `onViewChange` | `defaultView` |\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  date: search.date,\n  view: search.view,\n  onDateChange: date => navigate({ search: previous => ({ ...previous, date }) }),\n  onViewChange: view => navigate({ search: previous => ({ ...previous, view }) }),\n})\n```\n\nProp changes are reflected immediately. This matters for browser back/forward navigation: consumers do not need an effect that mutates a controller after render.\n\n## Geometry changes\n\nChanging `timeZone`, `weekStartsOn`, `dayStart`, `dayEnd`, or `slotDuration` recreates the underlying controller from the new value signature. The visible range therefore cannot retain initial configuration accidentally.\n",
  "/docs/api/use-create-calendar": "# useCreateCalendar\n\n> Create a controlled or uncontrolled item-agnostic controller, with optional simple-mode data.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-create-calendar\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  defaultDate: Temporal.PlainDate.from('2026-07-10'),\n  defaultView: 'month',\n  timeZone: 'America/Asuncion',\n  items: events,\n  getDate: event => event.date,\n})\n```\n\nWith `items`, the return value includes the inferred `activeView`. Without `items`, it returns the item-agnostic controller used with `CalendarProvider` and `useCalendarView`.\n\nControlled props are `date`/`onDateChange` and `view`/`onViewChange`; uncontrolled initial props are `defaultDate` and `defaultView`.\n",
  "/docs/api/use-calendar": "# useCalendar\n\n> Read the item-agnostic calendar controller from context.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-calendar\n\n```tsx\nfunction Toolbar() {\n  const calendar = useCalendar()\n  return (\n    <button onClick={calendar.next}>{calendar.title()}</button>\n  )\n}\n```\n\nThe hook accepts no item generic. Item types belong to `useCalendarView` calls below the provider.\n",
  "/docs/api/use-calendar-view": "# useCalendarView\n\n> Put events into one view from a shared calendar controller.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-calendar-view\n\n`useCalendarView` reads the controller from `CalendarProvider` unless you pass `calendar` directly. TypeScript infers the item type from `items`.\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCalendarView } from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  startsAt: Temporal.ZonedDateTime\n}\n\nfunction WeekContent({ events }: { events: Event[] }) {\n  const week = useCalendarView({\n    view: 'week',\n    items: events,\n    getDate: event => event.startsAt.toPlainDate(),\n    getStart: event => event.startsAt,\n  })\n\n  return week.days.map(day => (\n    <div key={day.id}>\n      {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n    </div>\n  ))\n}\n```\n\n`getDate` is required when you pass `items`. `getStart` is optional. Add it when events should appear in timed slots.\n",
  "/docs/api/calendar-provider": "# CalendarProvider\n\n> Share one calendar controller with child components.\n\nCanonical: https://calendar.gobrand.app/docs/api/calendar-provider\n\n```tsx\nimport {\n  CalendarProvider,\n  useCalendar,\n  useCreateCalendar,\n} from '@gobrand/react-calendar'\n\nfunction Calendar() {\n  const calendar = useCreateCalendar({ views: { month: true } })\n\n  return (\n    <CalendarProvider calendar={calendar}>\n      <Controls />\n      <VisibleRange />\n    </CalendarProvider>\n  )\n}\n\nfunction Controls() {\n  const calendar = useCalendar()\n\n  return (\n    <nav>\n      <button onClick={calendar.previous}>Previous</button>\n      <strong>{calendar.title()}</strong>\n      <button onClick={calendar.next}>Next</button>\n    </nav>\n  )\n}\n\nfunction VisibleRange() {\n  const { visibleRange } = useCalendar()\n\n  return <p>{visibleRange.start.toString()} – {visibleRange.end.toString()}</p>\n}\n```\n\nThe provider shares calendar state, not event data. Child views can fetch their own records and use their own item types.\n",
  "/docs/types/calendar": "# Calendar Controller\n\n> Item-agnostic calendar state, navigation, and visible query range.\n\nCanonical: https://calendar.gobrand.app/docs/types/calendar\n\n`CalendarController<TViews>` exposes `date`, `view`, typed `viewNames`, resolved `views`, `visibleRange`, `title`, `setDate`, `setView`, `next`, `previous`, `today`, and `subscribe`.\n\nDirect controllers preserve the exact configured-view union. Context exposes the honest built-in `ViewName` boundary because distant consumers cannot infer the provider's exact value.\n",
  "/docs/types/views": "# View Models\n\n> Discriminated month, week, and day models with locally inferred items.\n\nCanonical: https://calendar.gobrand.app/docs/types/views\n\n`MonthView<TItem>`, `WeekView<TItem>`, and `DayView<TItem>` are discriminated by their `name` field. `ActiveView<TViews, TItem>` narrows the union to the configured views.\n\nThe old `view` field remains as a deprecated alias for compatibility. New code should use `name`.\n\nTimed week and day configuration uses `Temporal.PlainTime` for `dayStart`/`dayEnd` and `Temporal.Duration` for `slotDuration`.\n",
  "/docs/types/helpers": "# Range and Configuration Types\n\n> Public types for configured views, geometry, and half-open query ranges.\n\nCanonical: https://calendar.gobrand.app/docs/types/helpers\n\n`VisibleRange` is `{ start, end }`, where both values are `Temporal.ZonedDateTime` instances in the controller timezone. Query with `>= start` and `< end`.\n\n`NonEmptyCalendarViews` enforces at least one of `month`, `week`, or `day`; JavaScript consumers receive the same validation synchronously at runtime.\n",
  "/docs/examples/basic-month": "# Month View\n\n> A complete month with navigation and events.\n\nCanonical: https://calendar.gobrand.app/docs/examples/basic-month\n\n<CalendarPreview name=\"basic-month\" />\n\nThe source imports small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n\nThis example needs only `getDate` because month cells group events by calendar date. Timed placement is introduced in the week and day examples.\n",
  "/docs/examples/date-picker": "# Date Picker\n\n> Select a date in a month without event data or accessors.\n\nCanonical: https://calendar.gobrand.app/docs/examples/date-picker\n\n<CalendarPreview name=\"date-picker\" />\n\nThe controller owns the selected date and navigation. A data-free month projection supplies the dates to render.\n",
  "/docs/examples/week-view": "# Week View\n\n> Build a simple week or add explicit time slots.\n\nCanonical: https://calendar.gobrand.app/docs/examples/week-view\n\n## Simple week\n\nEvents appear on each day.\n\n<CalendarPreview name=\"simple-week\" />\n\n## Week with time slots\n\nTimed events appear in an hourly grid.\n\n<CalendarPreview name=\"week-slots\" />\n\nBoth sources import small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n",
  "/docs/examples/day-view": "# Day View\n\n> A day timeline with explicit Temporal time slots.\n\nCanonical: https://calendar.gobrand.app/docs/examples/day-view\n\n<CalendarPreview name=\"day-view\" />\n\nThe source imports small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n",
  "/docs/examples/multi-view": "# Multi-View Calendar\n\n> One calendar that switches between month, week, and day.\n\nCanonical: https://calendar.gobrand.app/docs/examples/multi-view\n\n<CalendarPreview name=\"multi-view\" />\n\nThe source imports small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n\nThis example uses local events so view switching is the only new concept. See [Suspense Query](/docs/examples/suspense-query) for async data.\n",
  "/docs/examples/suspense-query": "# Suspense Query\n\n> Keep month navigation available while its events load.\n\nCanonical: https://calendar.gobrand.app/docs/examples/suspense-query\n\n<CalendarPreview name=\"suspense-month\" />\n\nThe controller and toolbar stay above the Suspense boundary. The query and month projection run below it after data is ready.\n",
  "/docs/core": "# Calendar Core\n\n> Framework-agnostic Temporal controller and pure calendar projections.\n\nCanonical: https://calendar.gobrand.app/docs/core\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill'\nimport { createCalendar, buildMonthView } from '@gobrand/calendar-core'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\nconst events: Event[] = [\n  { id: 'launch', title: 'Launch', date: Temporal.Now.plainDateISO() },\n]\n\nconst calendar = createCalendar({\n  views: { month: true },\n})\n\nconst month = buildMonthView({\n  calendar,\n  items: events,\n  getDate: event => event.date,\n})\n```\n\nThe calendar starts on today in the device timezone. Pass `date` or `timeZone` only when your app needs to control them.\n",
  "/docs/core/installation": "# Installation\n\n> Get started with GoBrand Calendar Core\n\nCanonical: https://calendar.gobrand.app/docs/core/installation\n\n## Install\n\n```bash\npnpm add @gobrand/calendar-core\n# or\nnpm install @gobrand/calendar-core\n```\n\n## TypeScript\n\nThe package is written in TypeScript and includes type definitions. No additional `@types` packages needed.\n\n## Temporal Polyfill\n\nThe Temporal API is included via `@js-temporal/polyfill`. You can import Temporal types directly from the polyfill:\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst today = Temporal.Now.plainDateISO();\nconst meeting = Temporal.ZonedDateTime.from('2025-01-20T14:00:00-05:00[America/New_York]');\n```\n",
  "/docs/core/create-calendar": "# createCalendar\n\n> Create an item-agnostic controller from a non-empty view configuration.\n\nCanonical: https://calendar.gobrand.app/docs/core/create-calendar\n\n```ts\nconst calendar = createCalendar({\n  views: {\n    month: true,\n    week: {\n      dayStart: Temporal.PlainTime.from('08:00'),\n      dayEnd: Temporal.PlainTime.from('18:00'),\n      slotDuration: Temporal.Duration.from({ minutes: 30 }),\n    },\n  },\n  date: Temporal.PlainDate.from('2026-07-10'),\n  timeZone: 'America/Asuncion',\n})\n```\n\nThe visible range is always derived from `date`, `view`, timezone, and view configuration. It cannot become stale independently.\n\n`weekStartsOn` follows Temporal's `dayOfWeek` convention: `1` is Monday through\n`7` is Sunday. Omit it to use the locale default.\n",
  "/docs/core/projections": "# View Projections\n\n> Build month, week, and day models from controller state and local data.\n\nCanonical: https://calendar.gobrand.app/docs/core/projections\n\nCore exports `buildMonthView`, `buildWeekView`, and `buildDayView`. Each projection infers its own item type, so one controller can support unrelated query results.\n\n```ts\nconst month = buildMonthView({\n  calendar,\n  items: summaries,\n  getDate: summary => summary.date,\n})\n\nconst week = buildWeekView({\n  calendar,\n  items: events,\n  getDate: event => event.startsAt.toPlainDate(),\n  getStart: event => event.startsAt,\n})\n```\n\nCalling a projection without `items` returns a data-free grid and needs no accessor or fake item type.\n",
  "/docs/core/visible-ranges": "# Visible ranges\n\n> Understand Calendar's timezone-aware, half-open query boundary.\n\nCanonical: https://calendar.gobrand.app/docs/core/visible-ranges\n\nEvery controller derives a `VisibleRange` from its date, active view, timezone, and week configuration:\n\n```ts\nconst { start, end } = calendar.visibleRange\n```\n\n`start` is included. `end` is the local midnight immediately after the visible interval and is excluded.\n\n```sql\nWHERE starts_at >= :start\n  AND starts_at < :end\n```\n\nMonth ranges include the complete leading and trailing weeks rendered by the month projection. Week ranges contain seven local dates. Day ranges span one local calendar date—even when DST makes that date 23 or 25 elapsed hours.\n\nCalendar produces `Temporal.ZonedDateTime` boundaries so callers can preserve the timezone or convert explicitly with `.toInstant()` for storage queries.\n",
  "/docs/core/utilities": "# Utilities\n\n> Formatting, navigation, and timezone helpers\n\nCanonical: https://calendar.gobrand.app/docs/core/utilities\n\n## Formatting\n\n### getWeekdays\n\nGet localized weekday names in the correct order for your calendar header.\n\n```typescript\nimport { getWeekdays } from '@gobrand/calendar-core';\n\ngetWeekdays();\n// [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"]\n\ngetWeekdays(7);                    // Sunday start\n// [\"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"]\n\ngetWeekdays(1, 'es-ES');           // Spanish\n// [\"lun\", \"mar\", \"mié\", \"jue\", \"vie\", \"sáb\", \"dom\"]\n\ngetWeekdays(1, 'en-US', 'long');   // Full names\n// [\"Monday\", \"Tuesday\", ...]\n\ngetWeekdays(7, 'en-US', 'narrow'); // Single letter\n// [\"S\", \"M\", \"T\", \"W\", \"T\", \"F\", \"S\"]\n```\n\n**Signature:**\n```typescript\nfunction getWeekdays(\n  weekStartsOn?: 1 | 2 | 3 | 4 | 5 | 6 | 7, // Temporal: 1 (Monday) through 7 (Sunday)\n  locale?: string | string[],                // Default: 'en-US'. Array for fallback locales\n  format?: 'long' | 'short' | 'narrow'       // Default: 'short'\n): string[];\n```\n\n### getMonthName\n\nGet localized month name from a `PlainYearMonth`.\n\n```typescript\nimport { getMonthName } from '@gobrand/calendar-core';\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst month = Temporal.PlainYearMonth.from('2025-01');\n\ngetMonthName(month);          // \"January\"\ngetMonthName(month, 'es-ES'); // \"enero\"\ngetMonthName(month, 'ja-JP'); // \"1月\"\n```\n\n### formatTime\n\nFormat a `PlainTime` for display.\n\n```typescript\nimport { formatTime } from '@gobrand/calendar-core';\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst time = Temporal.PlainTime.from('14:30');\n\nformatTime(time);          // \"2:30 PM\"\nformatTime(time, 'en-GB'); // \"14:30\"\n```\n\n## Timezone\n\n### getCurrentTimeZone\n\nGet the system's IANA timezone.\n\n```typescript\nimport { getCurrentTimeZone } from '@gobrand/calendar-core';\n\ngetCurrentTimeZone(); // \"America/New_York\"\n```\n\n### convertToTimezone\n\nConvert a `ZonedDateTime` to a different timezone.\n\n```typescript\nimport { convertToTimezone } from '@gobrand/calendar-core';\n\nconst ny = Temporal.ZonedDateTime.from('2025-01-15T14:00:00-05:00[America/New_York]');\nconst tokyo = convertToTimezone(ny, 'Asia/Tokyo');\n// 2025-01-16T04:00:00+09:00[Asia/Tokyo]\n```\n\n### createZonedDateTime\n\nCreate a `ZonedDateTime` from date and time components.\n\n```typescript\nimport { createZonedDateTime } from '@gobrand/calendar-core';\n\nconst date = Temporal.PlainDate.from('2025-01-15');\nconst time = Temporal.PlainTime.from('14:30');\nconst zdt = createZonedDateTime(date, time, 'America/New_York');\n// 2025-01-15T14:30:00-05:00[America/New_York]\n```\n\n## Navigation\n\nStandalone navigation functions for use outside `createCalendar`:\n\n```typescript\nimport {\n  nextMonth,\n  previousMonth,\n  nextWeek,\n  previousWeek,\n  nextDay,\n  previousDay,\n} from '@gobrand/calendar-core';\n\n// Month navigation\nconst jan = Temporal.PlainYearMonth.from('2025-01');\nnextMonth(jan);     // 2025-02\npreviousMonth(jan); // 2024-12\n\n// Week navigation\nconst date = Temporal.PlainDate.from('2025-01-15');\nnextWeek(date);     // 2025-01-22\npreviousWeek(date); // 2025-01-08\n\n// Day navigation\nnextDay(date);      // 2025-01-16\npreviousDay(date);  // 2025-01-14\n```\n\n## Date Ranges\n\nGet date ranges for the current period. Useful for data fetching.\n\n```typescript\nimport {\n  getMonthRange,\n  getWeekRange,\n  getDayRange,\n} from '@gobrand/calendar-core';\n\n// Ranges are aligned to week boundaries\nconst monthRange = getMonthRange('America/New_York', 1); // Monday start\n// { start: PlainDate, end: PlainDate }\n\nconst weekRange = getWeekRange('America/New_York', 1);\nconst dayRange = getDayRange('America/New_York');\n```\n\n## Layout Helpers\n\nFor rendering events in time-based views:\n\n### getEventPosition\n\nCalculate CSS position for an event block.\n\n```typescript\nimport { getEventPosition } from '@gobrand/calendar-core';\n\nconst position = getEventPosition(\n  eventStart,   // ZonedDateTime\n  eventEnd,     // ZonedDateTime\n  8,            // Day starts at 8 AM\n  60            // 60px per hour\n);\n// { top: 60, height: 90 }\n// Event starts 1 hour after 8 AM (top: 60px)\n// Event is 1.5 hours long (height: 90px)\n```\n\n### getTimeSlotHeight\n\nCalculate height for time slots.\n\n```typescript\nimport { getTimeSlotHeight } from '@gobrand/calendar-core';\n\ngetTimeSlotHeight(30, 60);  // 30px (half-hour slot at 60px/hour)\ngetTimeSlotHeight(15, 60);  // 15px (quarter-hour slot)\n```\n"
};
